PyFunc wrapper for diffusion model adapters saved with the ``mlflow.diffusers`` flavor.
"""

import io
import logging
from typing import Any, Optional

from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE

_logger = logging.getLogger(__name__)

_ADAPTER_WEIGHTS_DIR = "adapter_weights"
_BASE_MODEL_KEY = "base_model"
_BASE_MODEL_REVISION_KEY = "base_model_revision"
_WEIGHT_NAME_KEY = "weight_name"
_PROMPT_KEY = "prompt"


class _DiffusersAdapterWrapper:
    """PyFunc wrapper that loads a base diffusion pipeline and applies the saved adapter."""

    def __init__(
        self, adapter_path: str, flavor_conf: dict, model_config: Optional[dict] = None
    ) -> None:
        self._adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self._model_config = dict(model_config) if model_config else {}
        self._pipeline = None

    def _resolve_base_model(self) -> str:
        # An override supplied through ``model_config`` takes precedence over the base model
        # recorded in the flavor configuration.
        if _BASE_MODEL_KEY in self._model_config:
            return self._model_config[_BASE_MODEL_KEY]
        return self._flavor_conf[_BASE_MODEL_KEY]

    def _load_pipeline(self):
        import diffusers

        base_model = self._resolve_base_model()
        revision = self._flavor_conf.get(_BASE_MODEL_REVISION_KEY)

        from_pretrained_kwargs = {}
        # Only pass the revision when the base model is not overridden. An override may point at a
        # different repository for which the stored revision is meaningless.
        if revision and _BASE_MODEL_KEY not in self._model_config:
            from_pretrained_kwargs["revision"] = revision

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(
                base_model, **from_pretrained_kwargs
            )
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}'. Error: {e}",
                error_code=INVALID_PARAMETER_VALUE,
            ) from e

        weight_name = self._flavor_conf.get(_WEIGHT_NAME_KEY)
        load_kwargs = {"weight_name": weight_name} if weight_name else {}
        pipeline.load_lora_weights(self._adapter_path, **load_kwargs)

        from mlflow.diffusers import _detect_device

        device = _detect_device()
        if device:
            try:
                pipeline = pipeline.to(device)
            except Exception as e:
                _logger.warning(f"Failed to move pipeline to device '{device}': {e}")

        return pipeline

    def _get_pipeline(self):
        if self._pipeline is None:
            self._pipeline = self._load_pipeline()
        return self._pipeline

    def get_raw_model(self):
        """Return the underlying diffusion pipeline."""
        return self._get_pipeline()

    def _extract_prompts(self, data) -> list:
        import pandas as pd

        if isinstance(data, str):
            prompts = [data]
        elif isinstance(data, list):
            prompts = data
        elif isinstance(data, dict):
            if _PROMPT_KEY not in data:
                raise MlflowException(
                    f"Input dictionary must contain a '{_PROMPT_KEY}' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data[_PROMPT_KEY]
            if isinstance(value, str):
                prompts = [value]
            elif isinstance(value, list):
                prompts = value
            else:
                raise MlflowException(
                    f"The '{_PROMPT_KEY}' value must be a string or list of strings.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        elif isinstance(data, pd.DataFrame):
            if _PROMPT_KEY in data.columns:
                prompts = data[_PROMPT_KEY].tolist()
            elif len(data.columns) == 1:
                prompts = data[data.columns[0]].tolist()
            else:
                raise MlflowException(
                    f"Input DataFrame must contain a '{_PROMPT_KEY}' column.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        else:
            raise MlflowException(
                f"Unsupported input type: {type(data).__name__}. Supported types are str, "
                "list of str, dict with a 'prompt' key, and pandas.DataFrame.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if len(prompts) == 0:
            raise MlflowException(
                "No prompts were provided for inference.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if any(p is None for p in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return prompts

    def predict(self, data, params: Optional[dict[str, Any]] = None) -> list[bytes]:
        prompts = self._extract_prompts(data)
        pipeline = self._get_pipeline()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = getattr(output, "images", None)
        if images is None and isinstance(output, dict):
            images = output.get("images")

        if not images:
            raise MlflowException(
                "Pipeline returned no images.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return [_image_to_png_bytes(image) for image in images]


def _image_to_png_bytes(image) -> bytes:
    if isinstance(image, bytes):
        return image
    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()
